#include "manaengine/engine.hpp"
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
namespace py=pybind11; using namespace manaengine;
namespace {
py::dict card_dict(const ObservedCard& c){py::dict d;d["card_id"]=c.card_id;d["cost"]=c.cost;d["current_cost"]=c.current_cost;d["attack"]=c.attack;d["health"]=c.health;d["durability"]=c.durability;d["current_attack"]=c.current_attack;d["current_health"]=c.current_health;d["current_durability"]=c.current_durability;d["card_type"]=c.card_type;d["card_class"]=c.card_class;d["race"]=c.race;d["board_position"]=c.board_position;d["entity_id"]=c.entity_id;d["shatter_fragment"]=c.shatter_fragment;d["shatter_original_card_id"]=c.shatter_original_card_id;d["shatter_partner_hand_position"]=c.shatter_partner_hand_position;d["prepare_locked"]=c.prepare_locked;d["can_attack"]=c.can_attack;d["rush"]=c.rush;d["frozen"]=c.frozen;d["taunt"]=c.taunt;d["divine_shield"]=c.divine_shield;d["lifesteal"]=c.lifesteal;d["stealth"]=c.stealth;d["silenced"]=c.silenced;d["immune"]=c.immune;d["max_health"]=c.max_health;return d;}
py::dict player_dict(const ObservedPlayer& p){py::dict d;d["player_class"]=p.player_class;d["hero_health"]=p.hero_health;d["armor"]=p.armor;d["hero_attack"]=p.hero_attack;d["max_mana"]=p.max_mana;d["available_mana"]=p.available_mana;d["deck_size"]=p.deck_size;d["hand_size"]=p.hand_size;d["fatigue"]=p.fatigue;d["secret_count"]=p.secret_count;d["spell_damage"]=p.spell_damage;d["known_secrets"]=p.known_secrets;d["hero_power_ready"]=p.hero_power_ready;d["hero_frozen"]=p.hero_frozen;if(p.hero_power)d["hero_power"]=card_dict(*p.hero_power);else d["hero_power"]=py::none();if(p.weapon)d["weapon"]=card_dict(*p.weapon);else d["weapon"]=py::none();py::list board;for(const auto& c:p.board)board.append(card_dict(c));d["board"]=board;d["locations"]=py::list();return d;}
py::dict observation_dict(const Observation& o){py::dict d;d["turn_number"]=o.turn_number;d["active_player"]=o.active_player;d["self_player"]=player_dict(o.self_player);d["opponent"]=player_dict(o.opponent);py::list hand;for(const auto& c:o.self_hand)hand.append(card_dict(c));d["self_hand"]=hand;d["self_hand_known_count"]=o.self_hand_known_count;d["opponent_known_cards"]=py::list();return d;}
std::string action_name(ActionType t){switch(t){case ActionType::PlayCard:return "PLAY_CARD";case ActionType::PrepareCard:return "PREPARE_CARD";case ActionType::Attack:return "ATTACK";case ActionType::HeroPower:return "HERO_POWER";case ActionType::EndTurn:return "END_TURN";case ActionType::ChooseCard:return "CHOOSE_CARD";}return "UNKNOWN";}
py::dict action_dict(const Action& a){py::dict d;d["type"]=action_name(a.type);if(a.hand_index>=0)d["hand_index"]=a.hand_index;if(a.attacker_entity_id>=0)d["attacker_entity_id"]=a.attacker_entity_id;if(a.target_entity_id>=0)d["target_entity_id"]=a.target_entity_id;if(a.choice_index>=0)d["choice_index"]=a.choice_index;
 d["card_id"]=a.card_id;d["card_type"]=a.card_type;d["card_cost"]=a.card_cost;d["card_attack"]=a.card_attack;d["card_health"]=a.card_health;d["card_durability"]=a.card_durability;
 d["source_is_hero"]=a.source_is_hero;d["source_card_id"]=a.source_card_id;d["source_attack"]=a.source_attack;d["source_health"]=a.source_health;d["source_board_position"]=a.source_board_position;
 d["target_is_hero"]=a.target_is_hero;d["target_is_self"]=a.target_is_self;d["target_card_id"]=a.target_card_id;d["target_attack"]=a.target_attack;d["target_health"]=a.target_health;d["target_board_position"]=a.target_board_position;d["target_taunt"]=a.target_taunt;
 d["choice_card_id"]=a.choice_card_id;d["choice_card_type"]=a.choice_card_type;d["choice_card_cost"]=a.choice_card_cost;d["choice_card_attack"]=a.choice_card_attack;d["choice_card_health"]=a.choice_card_health;d["shatter_fragment"]=a.shatter_fragment;d["shatter_original_card_id"]=a.shatter_original_card_id;d["shatter_partner_hand_position"]=a.shatter_partner_hand_position;return d;}
Action action_from_dict(const py::dict& d){Action a;auto t=py::cast<std::string>(d["type"]);if(t=="PLAY_CARD"){a.type=ActionType::PlayCard;a.hand_index=py::cast<int>(d["hand_index"]);if(d.contains("target_entity_id"))a.target_entity_id=py::cast<int>(d["target_entity_id"]);}else if(t=="PREPARE_CARD"){a.type=ActionType::PrepareCard;a.hand_index=py::cast<int>(d["hand_index"]);}else if(t=="ATTACK"){a.type=ActionType::Attack;a.attacker_entity_id=py::cast<int>(d["attacker_entity_id"]);a.target_entity_id=py::cast<int>(d["target_entity_id"]);}else if(t=="HERO_POWER"){a.type=ActionType::HeroPower;a.target_entity_id=py::cast<int>(d["target_entity_id"]);}else if(t=="END_TURN")a.type=ActionType::EndTurn;else if(t=="CHOOSE_CARD"){a.type=ActionType::ChooseCard;a.choice_index=py::cast<int>(d["choice_index"]);if(d.contains("target_entity_id"))a.target_entity_id=py::cast<int>(d["target_entity_id"]);}else throw std::invalid_argument("unknown ManaEngine action type");return a;}
}
PYBIND11_MODULE(manaengine_native,m){
 py::register_exception<UnsupportedSimulationError>(m,"UnsupportedSimulationError");
 py::enum_<EffectKind>(m,"EffectKind").value("DAMAGE",EffectKind::Damage).value("DRAW",EffectKind::Draw).value("GAIN_ARMOR",EffectKind::GainArmor).value("MODIFY_HERO_ATTACK",EffectKind::ModifyHeroAttack).value("FREEZE",EffectKind::Freeze);
 py::enum_<DeckDrawFilter>(m,"DeckDrawFilter").value("ANY",DeckDrawFilter::Any).value("SPELL",DeckDrawFilter::Spell).value("FIRE_SPELL",DeckDrawFilter::FireSpell);
 py::enum_<TargetSelector>(m,"TargetSelector").value("EXPLICIT_CHARACTER",TargetSelector::ExplicitCharacter).value("EXPLICIT_ENEMY_CHARACTER",TargetSelector::ExplicitEnemyCharacter).value("EXPLICIT_MINION",TargetSelector::ExplicitMinion).value("ENEMY_MINIONS",TargetSelector::EnemyMinions).value("ENEMY_CHARACTERS",TargetSelector::EnemyCharacters).value("ALL_CHARACTERS",TargetSelector::AllCharacters).value("SELF",TargetSelector::Self);
 py::class_<EffectStep>(m,"EffectStep").def(py::init<>()).def_readwrite("kind",&EffectStep::kind).def_readwrite("target",&EffectStep::target).def_readwrite("amount",&EffectStep::amount).def_readwrite("lifesteal",&EffectStep::lifesteal);
 py::class_<CardDefinition>(m,"CardDefinition").def(py::init<>()).def_readwrite("card_id",&CardDefinition::card_id).def_readwrite("name",&CardDefinition::name).def_readwrite("card_type",&CardDefinition::card_type).def_readwrite("card_class",&CardDefinition::card_class).def_readwrite("race",&CardDefinition::race).def_readwrite("spell_school",&CardDefinition::spell_school).def_readwrite("ability",&CardDefinition::ability).def_readwrite("effects",&CardDefinition::effects).def_readwrite("generated_card",&CardDefinition::generated_card).def_readwrite("transform_card",&CardDefinition::transform_card).def_readwrite("support_state",&CardDefinition::support_state).def_readwrite("choice_pool",&CardDefinition::choice_pool).def_readwrite("shatter_left_card",&CardDefinition::shatter_left_card).def_readwrite("shatter_right_card",&CardDefinition::shatter_right_card).def_readwrite("choice_count",&CardDefinition::choice_count).def_readwrite("choice_cost_delta",&CardDefinition::choice_cost_delta).def_readwrite("collectible",&CardDefinition::collectible).def_readwrite("battlecry",&CardDefinition::battlecry).def_readwrite("prepare",&CardDefinition::prepare).def_readwrite("secret",&CardDefinition::secret).def_readwrite("secret_trigger",&CardDefinition::secret_trigger).def_readwrite("secret_effect",&CardDefinition::secret_effect).def_readwrite("random_cast_count",&CardDefinition::random_cast_count).def_readwrite("cost",&CardDefinition::cost).def_readwrite("attack",&CardDefinition::attack).def_readwrite("health",&CardDefinition::health).def_readwrite("durability",&CardDefinition::durability).def_readwrite("damage",&CardDefinition::damage).def_readwrite("pool_max_cost",&CardDefinition::pool_max_cost).def_readwrite("pool_count",&CardDefinition::pool_count).def_readwrite("duration",&CardDefinition::duration).def_readwrite("spell_cost_reduction_per_cast",&CardDefinition::spell_cost_reduction_per_cast).def_readwrite("held_spell_threshold",&CardDefinition::held_spell_threshold).def_readwrite("spell_damage",&CardDefinition::spell_damage).def_readwrite("damaged_spell_damage",&CardDefinition::damaged_spell_damage).def_readwrite("deathrattle_draw_count",&CardDefinition::deathrattle_draw_count).def_readwrite("deck_draw_filter",&CardDefinition::deck_draw_filter).def_readwrite("rush",&CardDefinition::rush).def_readwrite("taunt",&CardDefinition::taunt).def_readwrite("lifesteal",&CardDefinition::lifesteal);
 py::class_<CardCatalog,std::shared_ptr<CardCatalog>>(m,"CardCatalog").def(py::init<std::vector<CardDefinition>>(),py::arg("definitions"));
 py::class_<GameSession>(m,"GameSession").def(py::init<std::vector<std::string>,std::vector<std::string>,std::shared_ptr<CardCatalog>,std::uint64_t,bool,std::string,std::string>(),py::arg("player1_deck"),py::arg("player2_deck"),py::arg("catalog"),py::arg("seed")=0,py::arg("shuffle")=true,py::arg("player1_class")="UNKNOWN_CLASS",py::arg("player2_class")="UNKNOWN_CLASS").def("observation",[](const GameSession& s,const std::string& perspective){int p=perspective=="PLAYER2"?1:0;if(perspective=="ACTIVE")p=s.observation(0).active_player=="SELF"?0:1;return observation_dict(s.observation(p));},py::arg("perspective")="ACTIVE").def("legal_actions",[](const GameSession& s){py::list out;for(const auto& a:s.semantic_legal_actions())out.append(action_dict(a));return out;}).def("apply_action",[](GameSession& s,const py::dict& a){s.apply_action(action_from_dict(a));return observation_dict(s.observation(s.observation(0).active_player=="SELF"?0:1));}).def_property_readonly("is_complete",&GameSession::is_complete).def_property_readonly("is_valid",&GameSession::is_valid).def_property_readonly("unsupported_outcome",[](const GameSession& s)->py::object{auto r=s.unsupported_outcome();return r?py::cast(*r):py::none();}).def_property_readonly("result",[](const GameSession& s)->py::object{auto r=s.result();return r?py::cast(*r):py::none();}).def_property_readonly("needs_choice",&GameSession::needs_choice).def_property_readonly("choice_options",&GameSession::choice_options).def("clone",&GameSession::clone).def("begin_prototype_choice",&GameSession::begin_prototype_choice,py::arg("max_attack")=2).def_property_readonly("seed",&GameSession::seed).def("set_trace_enabled",&GameSession::set_trace_enabled,py::arg("enabled")).def_property_readonly("diagnostic_trace",[](const GameSession& s){return s.diagnostic_trace();});
}
